package kasperstudios.khgui.api.dialogs;

 import kasperstudios.khgui.api.ITheme;
 import net.minecraft.client.Minecraft;
 import net.minecraft.client.gui.GuiGraphics;
 import net.minecraft.client.gui.screens.Screen;
 import net.minecraft.network.chat.Component;
import org.lwjgl.glfw.GLFW;

import java.util.List;

/**
 * The actual generic Screen implementation generated by DialogBuilder.
 */
public class CustomDialogScreen extends Screen implements IDialog {
    private final Screen parent;
    private final String title;
    private final ITheme theme;
    private final int dialogWidth;
    private final int dialogHeight;
    private final List<IDialogElement> elements;
    private final List<IDialogButton> buttons;
    private final Runnable onCloseAction;

    private int scrollY = 0;

    private static final int HEADER_HEIGHT = 40;
    private static final int FOOTER_HEIGHT = 50;

    protected CustomDialogScreen(Screen parent, String title, ITheme theme, int width, int height,
            List<IDialogElement> elements, List<IDialogButton> buttons, Runnable onCloseAction) {
        super(Component.literal(title));
        this.parent = parent;
        this.title = title;
        this.theme = theme;
        this.dialogWidth = width;
        this.dialogHeight = height;
        this.elements = elements;
        this.buttons = buttons;
        this.onCloseAction = onCloseAction;
    }

    @Override
    public Screen getParent() {
        return parent;
    }

    @Override
    public String getDialogTitle() {
        return title;
    }

    @Override
    public ITheme getTheme() {
        return theme;
    }

    @Override
    public int getWidth() {
        return dialogWidth;
    }

    @Override
    public int getHeight() {
        return dialogHeight;
    }

    @Override
    public List<IDialogElement> getElements() {
        return elements;
    }

    @Override
    public void addElement(IDialogElement element) {
        this.elements.add(element);
    }

    @Override
    public List<IDialogButton> getButtons() {
        return buttons;
    }

    @Override
    public Runnable getOnClose() {
        return onCloseAction;
    }

    private int getActualDialogWidth() {
        return Math.min(dialogWidth, this.width - 40);
    }

    private int getActualDialogHeight() {
        return Math.min(dialogHeight, this.height - 40);
    }

    private int getDialogX() {
        return (this.width - getActualDialogWidth()) / 2;
    }

    private int getDialogY() {
        return (this.height - getActualDialogHeight()) / 2;
    }

    @Override
    public void renderBackground(GuiGraphics gfx, int mouseX, int mouseY, float delta) {
        // Overridden to prevent default Minecraft background blur
    }

    @Override
    public void render(GuiGraphics gfx, int mouseX, int mouseY, float delta) {
        gfx.fill(0, 0, this.width, this.height, 0xCC000000);

        int dx = getDialogX();
        int dy = getDialogY();
        int dw = getActualDialogWidth();
        int dh = getActualDialogHeight();

        gfx.fill(dx, dy, dx + dw, dy + dh, theme.getSidebarBackground());
        gfx.renderOutline(dx, dy, dw, dh, theme.getPrimaryAccent());

        renderHeader(gfx, dx, dy, dw, mouseX, mouseY);
        renderElements(gfx, dx, dy + HEADER_HEIGHT, dw, dh - HEADER_HEIGHT - FOOTER_HEIGHT, mouseX, mouseY, delta);
        renderFooter(gfx, dx, dy + dh - FOOTER_HEIGHT, dw, mouseX, mouseY);

        super.render(gfx, mouseX, mouseY, delta);
    }

    private void renderHeader(GuiGraphics gfx, int dx, int dy, int dw, int mouseX, int mouseY) {
        int hBg = adjustBrightness(theme.getSidebarBackground(), 10);
        gfx.fill(dx, dy, dx + dw, dy + HEADER_HEIGHT, hBg);
        gfx.drawString(this.font, title, dx + 16, dy + 14, theme.getPrimaryText(), true);

        int closeX = dx + dw - 36;
        int closeY = dy + 10;
        boolean hov = mouseX >= closeX && mouseX < closeX + 24 && mouseY >= closeY && mouseY < closeY + 20;
        gfx.fill(closeX, closeY, closeX + 24, closeY + 20, hov ? 0xFFF38BA8 : theme.getBorder());
        gfx.drawString(this.font, "✕", closeX + 8, closeY + 6, 0xFFFFFFFF, false);

        gfx.fill(dx, dy + HEADER_HEIGHT - 1, dx + dw, dy + HEADER_HEIGHT, theme.getBorder());
    }

    private void renderElements(GuiGraphics gfx, int dx, int dy, int dw, int listH, int mouseX, int mouseY,
            float delta) {
        gfx.enableScissor(dx, dy, dx + dw, dy + listH);

        int currentY = dy - scrollY;
        int totalHeight = 0;

        for (IDialogElement element : elements) {
            int elH = element.getHeight();
            if (currentY + elH >= dy && currentY <= dy + listH) {
                element.render(gfx, dx, currentY, dw, mouseX, mouseY, delta);
            }
            currentY += elH;
            totalHeight += elH;
        }

        gfx.disableScissor();

        // Scrollbar
        if (totalHeight > listH) {
            int sbH = Math.max(20, (listH * listH) / totalHeight);
            int sbY = dy + (scrollY * (listH - sbH)) / Math.max(1, totalHeight - listH);
            gfx.fill(dx + dw - 6, dy, dx + dw - 2, dy + listH, 0x22FFFFFF);
            gfx.fill(dx + dw - 6, sbY, dx + dw - 2, sbY + sbH, theme.getPrimaryAccent());
        }
    }

    private void renderFooter(GuiGraphics gfx, int dx, int dy, int dw, int mouseX, int mouseY) {
        gfx.fill(dx, dy, dx + dw, dy + FOOTER_HEIGHT, adjustBrightness(theme.getSidebarBackground(), 5));
        gfx.fill(dx, dy, dx + dw, dy + 1, theme.getBorder());

        int by = dy + 12;
        int btnW = 100;
        int currentX = dx + dw - 16 - btnW; // start from right

        // Add Close button always on right
        renderButton(gfx, "Close", currentX, by, btnW, theme.getBorder(), mouseX, mouseY);
        currentX -= (btnW + 10);

        // Custom buttons right-to-left
        for (int i = buttons.size() - 1; i >= 0; i--) {
            IDialogButton b = buttons.get(i);
            boolean hov = mouseX >= currentX && mouseX < currentX + btnW && mouseY >= by && mouseY < by + 28;
            int color = b.getColor(hov);
            renderButton(gfx, b.getText(), currentX, by, btnW, color, mouseX, mouseY);
            currentX -= (btnW + 10);
        }
    }

    private void renderButton(GuiGraphics gfx, String text, int x, int y, int w, int color, int mx, int my) {
        gfx.fill(x, y, x + w, y + 28, color);
        int tw = this.font.width(text);
        gfx.drawString(this.font, text, x + (w - tw) / 2, y + 10, 0xFFFFFFFF, true);
    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        int dx = getDialogX();
        int dy = getDialogY();
        int dw = getActualDialogWidth();
        int dh = getActualDialogHeight();

        // Header close
        int closeX = dx + dw - 36;
        int closeY = dy + 10;
        if (isOver(mouseX, mouseY, closeX, closeY, 24, 20)) {
            onClose();
            return true;
        }

        // Footer buttons
        int by = dy + dh - FOOTER_HEIGHT + 12;
        int btnW = 100;
        int currentX = dx + dw - 16 - btnW;

        if (isOver(mouseX, mouseY, currentX, by, btnW, 28)) { // Default close
            onClose();
            return true;
        }
        currentX -= (btnW + 10);

        for (int i = buttons.size() - 1; i >= 0; i--) {
            if (isOver(mouseX, mouseY, currentX, by, btnW, 28)) {
                buttons.get(i).onClick();
                return true;
            }
            currentX -= (btnW + 10);
        }

        // Elements
        int listY = dy + HEADER_HEIGHT;
        int listH = dh - HEADER_HEIGHT - FOOTER_HEIGHT;
        if (mouseY >= listY && mouseY < listY + listH && mouseX >= dx && mouseX < dx + dw) {
            for (IDialogElement element : elements) {
                if (element.mouseClicked(mouseX, mouseY, button)) {
                    return true;
                }
            }
        }

        return super.mouseClicked(mouseX, mouseY, button);
    }

    @Override
    public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
        if (keyCode == 256) { // ESC
            onClose();
            return true;
        }
        for (IDialogElement element : elements) {
            if (element.keyPressed(keyCode, scanCode, modifiers)) {
                return true;
            }
        }
        return super.keyPressed(keyCode, scanCode, modifiers);
    }

    @Override
    public boolean charTyped(char character, int modifiers) {
        for (IDialogElement element : elements) {
            if (element.charTyped(character, modifiers)) {
                return true;
            }
        }
        return super.charTyped(character, modifiers);
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double scrollX, double scrollYDelta) {
         int dh = getActualDialogHeight();
        int listH = dh - HEADER_HEIGHT - FOOTER_HEIGHT;
        int totalHeight = elements.stream().mapToInt(IDialogElement::getHeight).sum();
        int maxS = Math.max(0, totalHeight - listH);
        scrollY = Math.max(0, Math.min(maxS, scrollY - (int) (scrollYDelta * 20)));
        return true;
    }

    private boolean isOver(double mx, double my, int x, int y, int w, int h) {
        return mx >= x && mx < x + w && my >= y && my < y + h;
    }

    @Override
    public void onClose() {
        if (onCloseAction != null) {
            onCloseAction.run();
        }
        Minecraft.getInstance().setScreen(parent);
    }

    private int adjustBrightness(int color, int amount) {
        int a = (color >> 24) & 0xFF;
        int r = Math.max(0, Math.min(255, ((color >> 16) & 0xFF) + amount));
        int g = Math.max(0, Math.min(255, ((color >> 8) & 0xFF) + amount));
        int b = Math.max(0, Math.min(255, (color & 0xFF) + amount));
        return (a << 24) | (r << 16) | (g << 8) | b;
    }
}
